#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
// 발판을 벗어난 뒤2 tick까지 허용하는 자체 제작 점프 유예.
class JumpGrace {
    int left_ = 0;
    bool consumed_ = true;
public:
    void landed() { left_=2; consumed_=false; }
    void leftGround() { left_=2; }
    bool press() {
        if(consumed_ || left_<0) return false;
        consumed_=true; return true;
    }
    void airborneTick() { if(left_>=0)--left_; }
};
int main(){
    JumpGrace a;assert(!a.press());
    a.landed();a.leftGround();
    a.airborneTick();a.airborneTick();assert(a.press());
    assert(!a.press()); // 같은 유예에서 두 번 점프하지 않는다.
    JumpGrace b;b.landed();b.leftGround();
    b.airborneTick();b.airborneTick();b.airborneTick();
    assert(!b.press());
    for(int i=0;i<10000;++i)b.airborneTick();
    assert(!b.press());b.landed();assert(b.press());
    std::cout<<"grace tests passed\n";
}
